message.content:
{
  "candidate_edge_types": [
    {
      "name": "USES_PRIOR_RESULT_AS_INPUT",
      "definition": "A subsequent agent action consumes data or an artifact produced by an earlier execution step as an input to its own computation.",
      "source_description": "An earlier execution step or tool observation that produced data or an artifact used downstream.",
      "target_description": "A subsequent agent action that consumes that prior result as input."
    },
    {
      "name": "VERIFIES_OUTPUT_OF_PRIOR_ACTION",
      "definition": "A subsequent agent action performs a validation or check to determine whether the output produced by an earlier action satisfies required conditions.",
      "source_description": "An earlier action whose produced output is the subject of validation.",
      "target_description": "A subsequent agent action that checks or validates that output against requirements."
    },
    {
      "name": "RESOLVES_AMBIGUOUS_DATA_USING_RETRIEVED_REFERENCE",
      "definition": "An agent action uses previously retrieved reference data to interpret, disambiguate, or replace an unknown or ambiguous value found in another data source.",
      "source_description": "A previously retrieved reference observation containing the information needed to interpret the ambiguous value.",
      "target_description": "An agent action that resolves the ambiguous or unknown value using the retrieved reference data."
    },
    {
      "name": "INVESTIGATES_OBSERVED_DATA_ANOMALY",
      "definition": "An observation reveals an anomaly, placeholder, or missing value in retrieved data, prompting the agent to perform a follow-up investigation or retrieval to understand it.",
      "source_description": "An observation that reveals an anomaly, placeholder, or unknown value in retrieved data.",
      "target_description": "A subsequent agent action that investigates or retrieves information to understand or characterize the anomaly."
    },
    {
      "name": "JUSTIFIES_TASK_COMPLETION",
      "definition": "A passing verification result or set of satisfied constraints provides the basis for the agent's decision to conclude and mark the task as complete.",
      "source_description": "A verification result indicating that the required conditions are satisfied.",
      "target_description": "The agent decision to conclude or mark the task as complete."
    }
  ]
}

